//! `QSYSINC`, the system's include members: QS/400's own LDAP client
//! headers (docs/DIRSRV.md §13) in the source files `H` and
//! `QRPGLESRC`. The members are generated by `runtime/ldapclnt` into
//! `shipped/qsysinc/`; a member that differs from the shipped text is
//! written again, since the library is the system's.

use qsname::Name;
use store::obj::{JobHandle, ObjectId, types};
use store::txn::Txn;

/// The library.
pub const LIBRARY: &str = "QSYSINC";

/// The source files: name, record length, text.
pub const FILES: &[(&str, u32, &str)] = &[
    ("H", 92, "C include members"),
    ("QRPGLESRC", 112, "ILE RPG copy members"),
];

/// The members: source file, member, source type, text, contents.
pub const MEMBERS: &[(&str, &str, &str, &str, &str)] = &[
    (
        "H",
        "LDAP",
        "C",
        "LDAP client interface",
        include_str!("../shipped/qsysinc/H/LDAP.h"),
    ),
    (
        "H",
        "LBER",
        "C",
        "LDAP client BER interface",
        include_str!("../shipped/qsysinc/H/LBER.h"),
    ),
    (
        "H",
        "LDAPSSL",
        "C",
        "LDAP client secure connections",
        include_str!("../shipped/qsysinc/H/LDAPSSL.h"),
    ),
    (
        "QRPGLESRC",
        "LDAP",
        "RPGLE",
        "LDAP client interface for RPG",
        include_str!("../shipped/qsysinc/QRPGLESRC/LDAP.rpgle"),
    ),
];

fn name(s: &str) -> Result<Name, String> {
    Name::parse(s).map_err(|e| e.to_string())
}

/// The lines of a member as `write_member` takes them.
fn lines(text: &str) -> Vec<(u32, u32, String)> {
    text.lines()
        .enumerate()
        .map(|(i, l)| {
            (
                u32::try_from(i + 1).unwrap_or(u32::MAX).saturating_mul(100),
                0,
                l.to_string(),
            )
        })
        .collect()
}

/// The library, its source files and members, made or brought up to
/// date; how many objects and members were made or rewritten.
pub fn install(txn: &mut Txn<'_>, qsys: ObjectId, stamp: &wm::obj::Stamp) -> Result<usize, String> {
    let ctx = msgf::store::Ctx {
        now: stamp.now,
        owner: stamp.owner.clone(),
        system: stamp.system.clone(),
    };
    let (lib, made) =
        msgf::store::ensure_library(txn, &ctx, qsys, LIBRARY, "System include members")
            .map_err(|e| e.to_string())?;
    let mut n = usize::from(made);
    for (file, rcdlen, text) in FILES {
        let fname = name(file)?;
        let found = store::obj::library::Library::load(txn, lib)
            .and_then(|l| l.lookup(txn, types::FILE, fname))
            .map_err(|e| e.to_string())?;
        if found.is_none() {
            let opts = db::CreateFileOpts {
                text: (*text).to_string(),
                owner: stamp.owner.clone(),
                system: stamp.system.clone(),
                now: stamp.now,
                member: db::file::MemberOpt::None,
                max_members: 0,
                ..db::CreateFileOpts::default()
            };
            db::file::create_srcpf(txn, lib, fname, *rcdlen, &opts).map_err(|e| e.to_string())?;
            n += 1;
        }
    }
    for (file, member, srctype, text, contents) in MEMBERS {
        let fid = store::obj::library::Library::load(txn, lib)
            .and_then(|l| l.lookup(txn, types::FILE, name(file).expect("a name")))
            .map_err(|e| e.to_string())?
            .ok_or_else(|| format!("{LIBRARY}/{file} is missing"))?;
        let mname = name(member)?;
        let want = lines(contents);
        let current = db::source::read_member(txn, fid, qsname::MemberSpec::Name(mname))
            .ok()
            .map(|m| {
                m.records
                    .into_iter()
                    .map(|(_, _, t)| t.trim_end().to_string())
                    .collect::<Vec<_>>()
            });
        let wanted: Vec<String> = want
            .iter()
            .map(|(_, _, t)| t.trim_end().to_string())
            .collect();
        if current.as_ref() == Some(&wanted) {
            continue;
        }
        db::source::write_member(
            txn,
            JobHandle(0),
            fid,
            mname,
            &want,
            Some(name(srctype)?),
            text,
            stamp.now,
        )
        .map_err(|e| format!("{LIBRARY}/{file}({member}): {e}"))?;
        n += 1;
    }
    Ok(n)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn members_fit_their_files() {
        for (file, _, _, _, contents) in MEMBERS {
            let rcdlen = FILES.iter().find(|f| f.0 == *file).unwrap().1;
            let width = usize::try_from(rcdlen - 12).unwrap();
            for l in contents.lines() {
                assert!(l.len() <= width, "{file}: {l}");
            }
        }
    }
}
